/usr/bin/bash -lc "python - <<'PY'
def application_error():
    try:
        raise ValueError('application context')
    except ValueError:
        try:
            raise RuntimeError('application error')
        except RuntimeError as exc:
            return exc

for mode in ('inside', 'outside', 'from-chain'):
    exc = application_error()
    try:
        raise EOFError('internal stream')
    except EOFError:
        if mode == 'inside':
            try:
                raise exc
            except RuntimeError as raised:
                result = raised
        elif mode == 'from-chain':
            try:
                raise exc from exc.__cause__ or exc.__context__
            except RuntimeError as raised:
                result = raised
        else:
            pass
    if mode == 'outside':
        try:
            raise exc
        except RuntimeError as raised:
            result = raised
    print(mode, 'cause=', repr(result.__cause__), 'context=', repr(result.__context__), 'suppress=', result.__suppress_context__)
PY"

